#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countValidSubarraysWithMatchingDigits(std::vector<int>& nums, int d) {
        std::unordered_map<int, int> remCounts;
        remCounts[0] = 1;
        long long curSum = 0;
        long long ans = 0;
        for (int x : nums) {
            curSum = ((curSum + x) % d + d) % d;
            ans += remCounts[curSum];
            remCounts[curSum]++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countValidSubarraysWithMatchingDigits(int[] nums, int d) {
        Map<Integer, Integer> remCounts = new HashMap<>();
        remCounts.put(0, 1);
        long curSum = 0;
        long ans = 0;
        for (int x : nums) {
            curSum = ((curSum + x) % d + d) % d;
            ans += remCounts.getOrDefault((int)curSum, 0);
            remCounts.put((int)curSum, remCounts.getOrDefault((int)curSum, 0) + 1);
        }
        return ans;
    }
}

